def friendshipString(s: str) -> str:
    # 从右往左扫，维护右侧最小数字 mn。
    # 若当前数字比右边某个数字大，它留在原位会挡住更小的数字，必须被挪走（变成 min(d+1, 9)）；
    # 否则保留原值。最后所有数字都可以排成升序。
    mn = 10
    digits = []
    for ch in reversed(s):
        d = ord(ch) - 48
        if d > mn:
            digits.append(min(d + 1, 9))
        else:
            digits.append(d)
            mn = d
    digits.sort()
    return ''.join(map(str, digits))

if __name__ == "__main__":
    import sys
    data = sys.stdin.read().split()
    t = int(data[0])
    print('\n'.join(friendshipString(x) for x in data[1:1 + t]))
